const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function safe(value, fallback = null) {
  return value === undefined || value === null || value === "" ? fallback : value;
}

function getNestedDestination(source) {
  return source.destination || source.source_result?.destination || {};
}

function getNestedWrite(source) {
  return source.write || source.source_result?.write || {};
}

function classifyStatus(source) {
  if (source.error_log?.status === "logged") return "failed";
  if (source.approval?.status === "pending") return "pending_approval";
  if (source.routing?.status === "fallback") return "manual_review";
  if (source.notification?.status === "sent" && source.success === true) return "completed";
  if (source.write?.status === "created" && source.success === true) return "record_created";
  if (source.success === false) return "failed";
  return "in_progress";
}

function classifyStage(source) {
  if (source.error_log?.status === "logged") return "error_logged";
  if (source.approval?.status === "pending") return "approval_requested";
  if (source.routing?.status === "matched") return "route_matched";
  if (source.routing?.status === "fallback") return "manual_review";
  if (source.notification?.status === "sent") return "notification_sent";
  if (source.write?.status === "created") return "record_written";
  if (source.validation?.status === "passed") return "validated";
  if (source.validation?.status === "failed") return "validation_failed";
  return "received";
}

function classifyApprovalStatus(source) {
  if (source.approval?.status) return source.approval.status;
  return "not_required";
}

function classifyErrorStatus(source) {
  if (source.error_log?.status === "logged") return "logged";
  if (source.error) return "present";
  return "none";
}

function classifyRetryStatus(source) {
  if (source.error_log?.retry_status) return source.error_log.retry_status;
  return "not_required";
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C5-W",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        control_record: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const destination = getNestedDestination(source);
const write = getNestedWrite(source);
const createdAt = nowIso();

const currentStatus = config.current_status || classifyStatus(source);
const currentStage = config.current_stage || classifyStage(source);

const controlRecord = {
  record_type: "automation_status",
  event_id: safe(source.event_id),
  event_type: safe(source.event_type),
  current_status: currentStatus,
  current_stage: currentStage,
  owner: config.owner || source.error_log?.owner_email || source.approval?.reviewer_email || "unassigned",
  priority: config.priority || source.error_log?.severity || "normal",

  source_component: safe(source.component_id),
  source_component_version: safe(source.component_version),
  last_component: safe(source.component_id),

  destination_type: safe(destination.type),
  destination_record_id: safe(destination.record_id),
  write_status: safe(write.status),

  approval_id: safe(source.approval?.approval_id),
  approval_status: classifyApprovalStatus(source),
  approval_type: safe(source.approval?.approval_type),
  reviewer_email: safe(source.approval?.reviewer_email),

  error_id: safe(source.error_log?.error_id),
  error_status: classifyErrorStatus(source),
  error_code: safe(source.error_log?.source_error_code || source.error?.code),
  error_severity: safe(source.error_log?.severity),
  retry_status: classifyRetryStatus(source),
  retry_attempts: safe(source.error_log?.retry_attempts, 0),

  notification_channel: safe(source.notification?.channel || source.notification_payload?.channel),
  notification_status: safe(source.notification?.status),
  notification_to: safe(source.notification?.to || source.notification_payload?.to),

  next_action: config.default_next_action || source.next_action || "manual_review",
  manual_notes: config.manual_notes || "",
  created_at: config.created_at || createdAt,
  updated_at: createdAt
};

return [
  {
    json: {
      success: true,
      component_id: "C5-W",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      control_record: controlRecord,
      source_result: source,
      error: null,
      next_action: controlRecord.next_action
    }
  }
];
